echo '✅ panels/sanei.py بازنویسی شد'

echo "🔎 بررسی سینتکس فایل‌ها..."
for f in bot/handlers/admin.py bot/handlers/user.py bot/keyboards.py bot/middlewares.py bot/main.py database/crud.py database/db.py panels/sanei.py; do
  python3 -c "import ast; ast.parse(open('/opt/vpnbot/$f').read())" && echo "✅ $f سالم است" || echo "❌ خطای سینتکس در $f !!"
done

echo "🗄  بروزرسانی دیتابیس (ستون‌های جدید در صورت نیاز)..."
python3 << 'DBFIX'
import sqlite3
con = sqlite3.connect("/opt/vpnbot/vpnbot.db")
cur = con.cursor()

cur.execute("PRAGMA table_info(discount_codes)")
cols = [r[1] for r in cur.fetchall()]
if "expires_at" not in cols:
    cur.execute("ALTER TABLE discount_codes ADD COLUMN expires_at DATETIME")
    print("✅ ستون discount_codes.expires_at اضافه شد")
else:
    print("⏭️  ستون discount_codes.expires_at از قبل وجود دارد")

cur.execute("PRAGMA table_info(services)")
cols2 = [r[1] for r in cur.fetchall()]
if "panel_removed" not in cols2:
    cur.execute("ALTER TABLE services ADD COLUMN panel_removed BOOLEAN DEFAULT 0")
    print("✅ ستون services.panel_removed اضافه شد")
else:
    print("⏭️  ستون services.panel_removed از قبل وجود دارد")

con.commit()
con.close()
DBFIX

echo "🧹 پاک‌کردن __pycache__..."
find /opt/vpnbot -type d -name "__pycache__" -exec rm -rf {} + 2>/dev/null

echo "🔄 ری‌استارت سرویس..."
systemctl restart vpnbot
sleep 2
journalctl -u vpnbot -n 25 --no-pager
